#define _POSIX_C_SOURCE 200809L
#include <xcron.h>
#include <xrt/memory.h>
#include <inttypes.h>
#include <stdio.h>
#include <stdlib.h>
#if defined(_WIN32)
#include <windows.h>
static uint64 cpuStamp(void){ULONG64 N=0;if(!QueryThreadCycleTime(GetCurrentThread(),&N))exit(4);return (uint64)N;}
#define CPU_UNIT "thread_cycles"
#else
#include <time.h>
static uint64 cpuStamp(void){struct timespec T;if(clock_gettime(CLOCK_THREAD_CPUTIME_ID,&T))exit(4);return (uint64)T.tv_sec*1000000000+(uint64)T.tv_nsec;}
#define CPU_UNIT "thread_cpu_ns"
#endif
int main(int Argc,char** Argv)
{
    uint32 Count=Argc>1?(uint32)strtoul(Argv[1],NULL,10):1000000,Jobs=Argc>2?(uint32)strtoul(Argv[2],NULL,10):1;
    bool Budgeted=Argc>3 && strtoul(Argv[3],NULL,10)!=0;
    if(!Count || Count>1000000 || !Jobs || Jobs>10000)return 1;
    xcronscheduler* S=NULL;xcronzone* Z=NULL;xcronexpression E;xcronrun* Runs=NULL;int Exit=2;
    xcronschedulerconfig C={Jobs,Jobs,Jobs*3+1,0,64*1024*1024};uint64 Sum=0;
    if(!xcronZoneCreatePosix(XRT_STR_LITERAL("UTC0"),XCRON_ZONE_TZIF3,&Z,NULL) || !xcronExpressionCompile(XRT_STR_LITERAL("* * * * * *"),XCRON_SECONDS6,&E,NULL) ||
        !xcronSchedulerCreate(&C,&S,NULL) || !(Runs=xrtMalloc((size_t)Jobs*sizeof(*Runs))))goto Done;
    for(uint32 I=0;I<Jobs;++I){xcronjobconfig J={.Expression=E,.Zone=Z,.Begin=0,.End=INT64_MAX,.RunningLimit=1};xcronjobid Id;if(!xcronSchedulerAdd(S,&J,&Id,NULL))goto Done;}
    double Start=xrtTimer();uint64 CpuStart=cpuStamp();
    for(uint32 I=0;I<Count;++I){
        if(Budgeted){xcronpollbudgeted Q;if(!xcronSchedulerPollBudgeted(S,(xcronclock){(xtime)I*1000,(uint64)I*1000},(xcronzonedbudget){C.WorkLimit,C.WorkLimit,C.WorkLimit},Runs,Jobs,&Q,NULL) || Q.Poll.Count!=Jobs)goto Done;}
        else {xcronpoll P;if(!xcronSchedulerPoll(S,(xcronclock){(xtime)I*1000,(uint64)I*1000},Runs,Jobs,&P,NULL) || P.Count!=Jobs)goto Done;}
        for(uint32 J=0;J<Jobs;++J){Sum+=(uint64)Runs[J].ScheduledAt;if(!xcronSchedulerComplete(S,Runs[J].Id,XCRON_RUN_SUCCEEDED,NULL))goto Done;}
    }
    uint64 Cpu=cpuStamp()-CpuStart;double Elapsed=xrtTimer()-Start;if(!(Elapsed>0))goto Done;
    printf("dispatches_per_sec: %.3f\ncpu_units_per_dispatch: %.3f\ncpu_unit: " CPU_UNIT "\nbatch_size: %u\nchecksum: %" PRIu64 "\n",(double)Count*Jobs/Elapsed,(double)Cpu/Count/Jobs,Jobs,Sum);Exit=0;
Done:
    if(S){xcronSchedulerClose(S,NULL);xcronretired R;bool Found;do{Found=false;xcronSchedulerReap(S,&R,&Found,NULL);}while(Found);if(!xcronSchedulerDestroy(S,NULL))Exit=3;}
    xrtFree(Runs);xcronZoneRelease(Z);xrtClearError();return Exit;
}
